# Log 0F: Cassels-Tate pairing on the 2-Selmer group of E: y^2=(x-e1)(x-e2)(x-e3) (all e_i in Z).
# Formula: Cassels 1998 "Second descents for elliptic curves", in the form (3.10) of Shukla-Stoll, arXiv:2302.01640.
# Needs code_sel2_rho.py in the same folder. Needs: sympy (mpmath comes with it).
# Usage:  python3 code_ct_cassels.py congruent 17 34 41 65     (validation on y^2=x^3-n^2 x)
#         python3 code_ct_cassels.py target 25716 29244          (K=729 family, B=+1 factor-shape curves, j = index in u=17627+34440 j)
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import random, itertools
from fractions import Fraction
from math import gcd, isqrt
from sympy import factorint, legendre_symbol as ls
from code_sel2_rho import cls_odd, cls_2, span_basis, annihilator, rank_f2, local_image_2, PQ_from_u

def vp(n,p):
    n=abs(n)
    if n==0: return 10**9
    c=0
    while n%p==0: n//=p; c+=1
    return c
def sqf(n):
    s=1 if n>0 else -1; n=abs(n); r=1
    for p,k in factorint(n).items():
        if k%2: r*=p
    return s*r

# ---------------- general Sel^2 (local images by sampling) ----------------
def rand_unit(v): return random.randint(1,v-1) if v>2 else random.choice([1,3,5,7])
def in_sq_Qv(f,v):
    if f==0: return False
    k=vp(f.numerator,v)-vp(f.denominator,v)
    if k%2: return False
    return (cls_odd(f,v)[1]==0) if v>2 else (cls_2(f)[1:]==(0,0))
def local_image(e,v,samples=400):
    e1,e2,e3=e; pts=set(); cls=(lambda r:cls_odd(r,v)) if v>2 else cls_2
    d12,d13,d23=e1-e2,e1-e3,e2-e3
    pts.add(cls(Fraction(d12*d13))+cls(Fraction(d12)))
    pts.add(cls(Fraction(e2-e1))+cls(Fraction((e2-e1)*(e2-e3))))
    pts.add(cls(Fraction(e3-e1))+cls(Fraction(e3-e2)))
    target=2 if v>2 else 3
    for t in range(samples*20):
        base=random.choice([0,e1,e2,e3,random.randint(-50,50)])
        k=random.choice([0,0,1,1,2,3]); u=rand_unit(v)*random.choice([1,1,1])+ (v if (t%7==0) else 0)
        if t%5==0: x=Fraction(u, v**(2*random.choice([1,2])))
        else: x=Fraction(base)+Fraction(v)**k*u
        f=(x-e1)*(x-e2)*(x-e3)
        if x in (e1,e2,e3) or f==0 or not in_sq_Qv(f,v): continue
        pts.add(cls(x-e1)+cls(x-e2))
        if len(span_basis([list(p) for p in pts]))>=target and t>samples: break
    B=span_basis([list(p) for p in pts])
    assert len(B)==target,(v,len(B),target)
    return B
def real_image(e):
    es=sorted(e); pts=set()
    for x in [es[0]+0.5*(es[1]-es[0]), es[2]+1, es[2]+100]:
        f=(x-e[0])*(x-e[1])*(x-e[2])
        if f>0: pts.add(((x-e[0])<0, (x-e[1])<0))
    return span_basis([[int(a),int(b)] for a,b in pts])
def sel2_general(e):
    e1,e2,e3=e
    D=abs((e1-e2)*(e1-e3)*(e2-e3)); primes=sorted(set([2]+list(factorint(D).keys())))
    gens=[-1]+primes; n=len(gens); rows=[]
    def addc(B,dim,clsfun):
        ann=annihilator(B,2*dim)
        for h in ann:
            row=[0]*(2*n)
            for gi,g in enumerate(gens):
                ca=clsfun(g)
                for t in range(dim):
                    if h[t] and ca[t]: row[gi]^=1
                    if h[dim+t] and ca[t]: row[n+gi]^=1
            rows.append(row)
    for v in primes:
        if v==2: addc(local_image(e,2),3,lambda g:list(cls_2(Fraction(g))))
        else: addc(local_image(e,v),2,lambda g,v=v:list(cls_odd(Fraction(g),v)))
    addc(real_image(e),1,lambda g:[1 if g<0 else 0])
    ker=annihilator(rows,2*n)
    els=[]
    for k in ker:
        a=1;b=1
        for gi,g in enumerate(gens):
            if k[gi]: a*=g
            if k[n+gi]: b*=g
        els.append((sqf(a),sqf(b)))
    return els,gens,primes
def elt_group(els):
    """all elements of the group spanned (as pairs (b1,b2); the third class is b1*b2)"""
    S={(1,1)}
    for a,b in els:
        S|={(sqf(x*a),sqf(y*b)) for x,y in S}
    return S
# ---------------- Hilbert symbol (bit: 0 for +1, 1 for -1); v=0 is the real place ----------------
def hilb(a,b,v):
    a=Fraction(a); b=Fraction(b)
    a=a.numerator*a.denominator; b=b.numerator*b.denominator
    if v==0: return 1 if (a<0 and b<0) else 0
    al=vp(a,v); be=vp(b,v); u=a//(v**al); w=b//(v**be)
    if v==2:
        eps=lambda z:((z-1)//2)%2; om=lambda z:((z*z-1)//8)%2
        return (eps(u)*eps(w)+al*om(w)+be*om(u))%2
    r=(al*be*((v-1)//2))%2
    if be%2: r+= 0 if ls(u%v,v)==1 else 1
    if al%2: r+= 0 if ls(w%v,v)==1 else 1
    return r%2
# ---------------- p-adic square root approximations ----------------
def padic_sqrt(c,v,N):
    """approx sqrt of c in Q_v (c Fraction, square in Q_v) as Fraction, precision ~ v^N relative"""
    k=vp(c.numerator,v)-vp(c.denominator,v); assert k%2==0
    u=c/Fraction(v)**k
    M=v**(N+3)
    un=(u.numerator*pow(u.denominator,-1,M))%M
    if v==2:
        assert un%8==1,un
        r=1
        for kk in range(3,N+3):
            if (r*r-un)%(2**(kk+1))!=0: r+=2**(kk-1)
        r%=M
    else:
        from sympy.ntheory import sqrt_mod
        r=sqrt_mod(un%v,v); assert r is not None
        r=int(r)
        mod=v
        while mod<M:       # Hensel/Newton
            mod=min(mod*mod,M); r=(r-(r*r-un)*pow(2*r,-1,mod))%mod
    return Fraction(r)*Fraction(v)**(k//2)
# ---------------- global conic points (brute force; used only for the generic validation) ----------------
def conic_point(A,B,C,bound=400):
    """primitive integer (X,Y,Z)!=0 with A X^2+B Y^2+C Z^2=0"""
    for Z in range(0,bound+1):
        for X in range(-bound,bound+1):
            if X==0 and Z==0: continue
            rhs=-(A*X*X+C*Z*Z)
            if rhs%B==0 and rhs//B>=0:
                Y2=rhs//B; Y=isqrt(Y2)
                if Y*Y==Y2:
                    g=gcd(gcd(X,Y),Z)
                    if g: return (X//g,Y//g,Z//g)
    return None
def global_points(e,beta):
    """q_i=(Gj*,Gk*,T*) with beta_j Gj^2 - beta_k Gk^2 + (e_j-e_k) T^2 = 0 ; (i,j,k) cyclic (0-based)"""
    qs={}
    for i in range(3):
        j=(i+1)%3; k=(i+2)%3
        pt=conic_point(beta[j],-beta[k],e[j]-e[k])
        if pt is None: return None
        qs[i]=(j,k,pt)
    return qs
# ---------------- local points on D_a ----------------
def local_point(e,beta,v,tries=200000):
    e1,e2,e3=e; cls=(lambda r:cls_odd(r,v)) if v>2 else cls_2
    cb=[cls(Fraction(b)) for b in beta]
    for t in range(tries):
        base=random.choice([e1,e2,e3,0,random.randint(-30,30)])
        k=random.choice([0,0,1,1,2,3]); u=rand_unit(v)+(v if t%7==0 else 0)
        if t%4==0: x=Fraction(u,v**(2*random.choice([1,2])))
        else: x=Fraction(base)+Fraction(v)**k*u
        if x in (e1,e2,e3): continue
        if cls(x-e1)==cb[0] and cls(x-e2)==cb[1] and cls(x-e3)==cb[2]: return x
    raise RuntimeError("no local point")

def coeffs(e,beta,qs,primitive=False):
    """tangent forms L_i = A_j G_j + A_k G_k + A_T T of H_i at q_i; primitive=True divides by the content"""
    out={}
    for i in range(3):
        j,k,(Gj,Gk,T)=qs[i]
        t=(Fraction(2*beta[j]*Gj,e[j]-e[k]),Fraction(-2*beta[k]*Gk,e[j]-e[k]),Fraction(2*T))
        if primitive:
            from math import lcm
            den=lcm(*[c.denominator for c in t]); ints=[int(c*den) for c in t]
            g=gcd(gcd(ints[0],ints[1]),ints[2])
            t=tuple(Fraction(z//g) for z in ints)     # rescaling by a positive rational: allowed by Hilbert reciprocity when all places are summed
        out[i]=t
    return out
def primes_of_fr(fr):
    ps=set()
    for z in (fr.numerator,fr.denominator):
        if abs(z)>1: ps|=set(factorint(abs(z)).keys())
    return ps
def place_value(e,beta,betap,qs,C,v,Nprec=16,reps=1):
    """sum_i (L_i(q_v),beta_i')_v for random non-degenerate local points q_v; returns the set of values seen (must be one value)."""
    vals=set()
    for r in range(reps):
        for attempt in range(200):
            x=local_point(e,beta,v)
            G=[padic_sqrt((x-e[i])/Fraction(beta[i]),v,Nprec)*random.choice([1,-1]) for i in range(3)]
            tot=0; good=True
            for i in range(3):
                j,k,_=qs[i]; Aj,Ak,AT=C[i]
                L=Aj*G[j]+Ak*G[k]+AT
                if L==0: good=False;break
                val=vp(L.numerator,v)-vp(L.denominator,v)
                if val>=Nprec-2: good=False;break
                tot+=hilb(L,betap[i],v)
            if good: vals.add(tot%2); break
        else: raise RuntimeError("no non-degenerate local point at %d"%v)
    return vals
def real_contribution(e,beta,betap,qs,C,xs=None):
    import mpmath
    mpmath.mp.dps=90
    es=sorted(e)
    cands=xs or [es[0]-10**6, es[0]-1, es[2]+1, es[2]+10**6, es[1]+(es[2]-es[1])/3, es[0]+(es[1]-es[0])/3, es[0]+(es[1]-es[0])*2/3]
    res=set()
    for x in cands:
        x=Fraction(x)
        if not all(((x-e[i])>0)==(beta[i]>0) for i in range(3)): continue
        G=[mpmath.sqrt(abs(mpmath.mpf((x-e[i]).numerator))/mpmath.mpf((x-e[i]).denominator)/abs(mpmath.mpf(beta[i]))) for i in range(3)]
        for sg in [(1,1,1),(1,-1,1),(-1,1,-1)]:
            tot=0
            for i in range(3):
                j,k,_=qs[i]; Aj,Ak,AT=C[i]
                L=mpmath.mpf(Aj.numerator)/Aj.denominator*sg[j]*G[j]+mpmath.mpf(Ak.numerator)/Ak.denominator*sg[k]*G[k]+mpmath.mpf(AT.numerator)/AT.denominator
                tot+= 1 if (L<0 and betap[i]<0) else 0
            res.add(tot%2)
    if len(res)!=1: raise RuntimeError("real place value depends on point/sign: %s"%res)
    return res.pop()
def pairing_bit(e,beta,betap,qs,places,Nprec=16,reps=1,primitive=False):
    C=coeffs(e,beta,qs,primitive); tot=0
    for v in places:
        if v==0:
            tot+=real_contribution(e,beta,betap,qs,C)
            continue
        vals=place_value(e,beta,betap,qs,C,v,Nprec,reps)
        if len(vals)>1: raise RuntimeError("place %d value depends on local point: %s"%(v,vals))
        tot+=vals.pop()
    return tot%2
def all_places(e,beta,betap,qs):
    D=abs((e[0]-e[1])*(e[0]-e[2])*(e[1]-e[2])); ps=set([2])|set(factorint(D).keys())
    for b in list(beta)+list(betap):
        if abs(b)>1: ps|=set(factorint(abs(b)).keys())
    C=coeffs(e,beta,qs)
    for i in C:
        for c in C[i]: ps|=primes_of_fr(c)
    for i in range(3):
        j,k,(Gj,Gk,T)=qs[i]
        for z in (Gj,Gk,T):
            if abs(z)>1: ps|=set(factorint(abs(z)).keys())
    return sorted(ps)+[0]
def places_S(e,beta,betap,factD=None):
    D=abs((e[0]-e[1])*(e[0]-e[2])*(e[1]-e[2])); ps=set([2])|set((factD or factorint(D)).keys())
    for b in list(beta)+list(betap):
        if abs(b)>1: ps|=set(factorint(abs(b)).keys())
    return sorted(ps)+[0]
def ct(e,a,ap,places=None,seed=0,qs_override=None,reps=1,primitive=False):
    """Cassels-Tate pairing bit <a,ap> on Sel^2 (a=(a1,a2)=([x-e1],[x-e2]) etc.)"""
    random.seed(seed)
    beta=(a[0],a[1],sqf(a[0]*a[1])); betap=(ap[0],ap[1],sqf(ap[0]*ap[1]))
    qs=qs_override or global_points(e,beta)
    if qs is None: return None
    if places is None: places=places_S(e,beta,betap) if primitive else all_places(e,beta,betap,qs)
    return pairing_bit(e,beta,betap,qs,places,reps=reps,primitive=primitive)

# ======================= validation on congruent number curves =======================
def congruent(ns):
    for n in ns:
        e=(-n,0,n); random.seed(n)
        els,gens,primes=sel2_general(e); d=len(els)
        print("n=%d dim Sel2=%d"%(n,d),flush=True)
        if d<4: continue
        M=[[ct(e,els[i],els[j],seed=1,reps=2,primitive=True) for j in range(d)] for i in range(d)]
        rows=[int(''.join(map(str,r)),2) for r in M]; b=[]; rk=0
        for r in rows:
            for x in b: r=min(r,r^x)
            if r: b.append(r); rk+=1
        print("  basis",els,"\n  pairing matrix",M,"rank",rk,flush=True)

# ======================= K=729 family: <(1,e), w2> on the B=+1 factor-shape curves =======================
K=729
def selmer_elements(P,Q):
    # Sel^2 of y^2=x(x-P^2)(x-Q^2) by the local images of 36-09EM/EN (as in code_sel2_symbolic_model / code_verify_09)
    D=abs(P*P-Q*Q)
    fP=[p for p in factorint(P) if p%2]; fQ=[p for p in factorint(Q) if p%2]
    fD=[p for p in factorint(D) if p%2 and p not in fP and p not in fQ]
    odd=sorted(fP+fQ+fD); gens=[-1,2]+odd; n=len(gens); rows=[]
    def addc(B,dim,cf):
        for h in annihilator(B,2*dim):
            row=[0]*(2*n)
            for gi,g in enumerate(gens):
                ca=cf(g)
                for t in range(dim):
                    if h[t] and ca[t]: row[gi]^=1
                    if h[dim+t] and ca[t]: row[n+gi]^=1
            rows.append(row)
    for v in odd:
        if v in fP: B=span_basis([[0,1,0,1],[0,0,0,1] if v%4==3 else [1,0,1,0]])
        elif v in fQ: B=span_basis([[0,1,0,0],[0,0,0,1] if v%4==3 else [1,0,0,0]])
        else: B=span_basis([[0,0,1,0],[0,0,0,1]])
        addc(B,2,lambda g,v=v:list(cls_odd(Fraction(g),v)))
    addc(local_image_2(P,Q),3,lambda g:list(cls_2(Fraction(g))))
    addc([[0,1]],1,lambda g:[1 if g<0 else 0])
    ker=annihilator(rows,2*n); els=[]
    for k in ker:
        a=1;b=1
        for gi,g in enumerate(gens):
            if k[gi]: a*=g
            if k[n+gi]: b*=g
        els.append((sqf(a),sqf(b)))
    return els
def target(j,seeds=(1,2)):
    u=17627+34440*j; P,Q=PQ_from_u(u); P=abs(P); Q=abs(Q)
    d,f,e=u,2*u+K,4*u+K
    els=selmer_elements(P,Q); G=elt_group(els)
    w1=(1,e); tors=[(1,-1),(1,sqf(-d*f*e))]
    assert w1 in G
    w2=[g for g in G if g not in elt_group([w1]+tors)][0]
    e3=(0,P*P,Q*Q); beta=(1,e,e); betap=(w2[0],w2[1],sqf(w2[0]*w2[1]))
    t=16*K*d*f      # t = (Q^2-P^2)/e
    qs={0:(1,2,(t+1,t-1,2)),1:(2,0,(0,Q,1)),2:(0,1,(P,0,1))}      # rational points on the three conics H_i
    for i in range(3):
        jj,kk,(X,Y,Z)=qs[i]; assert beta[jj]*X*X-beta[kk]*Y*Y+(e3[jj]-e3[kk])*Z*Z==0
    primes={2,3,d,e,f,7,41}|set(factorint(P))|set(factorint(Q))
    for b in list(beta)+list(betap):
        if abs(b)>1: primes|=set(factorint(abs(b)))
    from sympy import primerange
    places=sorted(primes|set(primerange(2,60)))+[0]
    out=[]
    for s in seeds:
        random.seed(s); out.append(pairing_bit(e3,beta,betap,qs,places,reps=2,primitive=True))
    chk=[]   # torsion classes must pair to 0
    for tt in tors:
        bt=(tt[0],tt[1],sqf(tt[0]*tt[1])); random.seed(5)
        pl=sorted(set(places)|{p for x in bt if abs(x)>1 for p in factorint(abs(x))}-{0})+[0]
        chk.append(pairing_bit(e3,beta,bt,qs,pl,reps=2,primitive=True))
    print({"j":j,"u":u,"dimSel2":len(els),"w2":w2,"pairing <(1,e),w2>":out,"torsion check":chk},flush=True)

if __name__=="__main__":
    if sys.argv[1]=="congruent": congruent([int(x) for x in sys.argv[2:]])
    else:
        for j in sys.argv[2:]: target(int(j))

# Log 0F/0H (v2): Cassels-Tate pairing on the 2-Selmer group of E: y^2=(x-e1)(x-e2)(x-e3) (all e_i in Z).
# Formula: Cassels 1998 "Second descents for elliptic curves", in the form (3.10) of Shukla-Stoll, arXiv:2302.01640.
# v2 change (log 0H): pairing_bit() now sums every place exactly once (a duplicated real place cancels in pairs);
#                     the torsion check in target() had the same duplication (operator precedence), now fixed.
# Needs code_sel2_rho.py in the same folder. Needs: sympy (mpmath comes with it).
# Usage:  python3 code_ct_cassels.py congruent 17 34 41 65     (validation on y^2=x^3-n^2 x)
#         python3 code_ct_cassels.py target 25716 29244          (K=729 family, B=+1 factor-shape curves, j = index in u=17627+34440 j)
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import random, itertools
from fractions import Fraction
from math import gcd, isqrt
from sympy import factorint, legendre_symbol as ls
from code_sel2_rho import cls_odd, cls_2, span_basis, annihilator, rank_f2, local_image_2, PQ_from_u

def vp(n,p):
    n=abs(n)
    if n==0: return 10**9
    c=0
    while n%p==0: n//=p; c+=1
    return c
def sqf(n):
    s=1 if n>0 else -1; n=abs(n); r=1
    for p,k in factorint(n).items():
        if k%2: r*=p
    return s*r

# ---------------- general Sel^2 (local images by sampling) ----------------
def rand_unit(v): return random.randint(1,v-1) if v>2 else random.choice([1,3,5,7])
def in_sq_Qv(f,v):
    if f==0: return False
    k=vp(f.numerator,v)-vp(f.denominator,v)
    if k%2: return False
    return (cls_odd(f,v)[1]==0) if v>2 else (cls_2(f)[1:]==(0,0))
def local_image(e,v,samples=400):
    e1,e2,e3=e; pts=set(); cls=(lambda r:cls_odd(r,v)) if v>2 else cls_2
    d12,d13,d23=e1-e2,e1-e3,e2-e3
    pts.add(cls(Fraction(d12*d13))+cls(Fraction(d12)))
    pts.add(cls(Fraction(e2-e1))+cls(Fraction((e2-e1)*(e2-e3))))
    pts.add(cls(Fraction(e3-e1))+cls(Fraction(e3-e2)))
    target=2 if v>2 else 3
    for t in range(samples*20):
        base=random.choice([0,e1,e2,e3,random.randint(-50,50)])
        k=random.choice([0,0,1,1,2,3]); u=rand_unit(v)*random.choice([1,1,1])+ (v if (t%7==0) else 0)
        if t%5==0: x=Fraction(u, v**(2*random.choice([1,2])))
        else: x=Fraction(base)+Fraction(v)**k*u
        f=(x-e1)*(x-e2)*(x-e3)
        if x in (e1,e2,e3) or f==0 or not in_sq_Qv(f,v): continue
        pts.add(cls(x-e1)+cls(x-e2))
        if len(span_basis([list(p) for p in pts]))>=target and t>samples: break
    B=span_basis([list(p) for p in pts])
    assert len(B)==target,(v,len(B),target)
    return B
def real_image(e):
    es=sorted(e); pts=set()
    for x in [es[0]+0.5*(es[1]-es[0]), es[2]+1, es[2]+100]:
        f=(x-e[0])*(x-e[1])*(x-e[2])
        if f>0: pts.add(((x-e[0])<0, (x-e[1])<0))
    return span_basis([[int(a),int(b)] for a,b in pts])
def sel2_general(e):
    e1,e2,e3=e
    D=abs((e1-e2)*(e1-e3)*(e2-e3)); primes=sorted(set([2]+list(factorint(D).keys())))
    gens=[-1]+primes; n=len(gens); rows=[]
    def addc(B,dim,clsfun):
        ann=annihilator(B,2*dim)
        for h in ann:
            row=[0]*(2*n)
            for gi,g in enumerate(gens):
                ca=clsfun(g)
                for t in range(dim):
                    if h[t] and ca[t]: row[gi]^=1
                    if h[dim+t] and ca[t]: row[n+gi]^=1
            rows.append(row)
    for v in primes:
        if v==2: addc(local_image(e,2),3,lambda g:list(cls_2(Fraction(g))))
        else: addc(local_image(e,v),2,lambda g,v=v:list(cls_odd(Fraction(g),v)))
    addc(real_image(e),1,lambda g:[1 if g<0 else 0])
    ker=annihilator(rows,2*n)
    els=[]
    for k in ker:
        a=1;b=1
        for gi,g in enumerate(gens):
            if k[gi]: a*=g
            if k[n+gi]: b*=g
        els.append((sqf(a),sqf(b)))
    return els,gens,primes
def elt_group(els):
    """all elements of the group spanned (as pairs (b1,b2); the third class is b1*b2)"""
    S={(1,1)}
    for a,b in els:
        S|={(sqf(x*a),sqf(y*b)) for x,y in S}
    return S
# ---------------- Hilbert symbol (bit: 0 for +1, 1 for -1); v=0 is the real place ----------------
def hilb(a,b,v):
    a=Fraction(a); b=Fraction(b)
    a=a.numerator*a.denominator; b=b.numerator*b.denominator
    if v==0: return 1 if (a<0 and b<0) else 0
    al=vp(a,v); be=vp(b,v); u=a//(v**al); w=b//(v**be)
    if v==2:
        eps=lambda z:((z-1)//2)%2; om=lambda z:((z*z-1)//8)%2
        return (eps(u)*eps(w)+al*om(w)+be*om(u))%2
    r=(al*be*((v-1)//2))%2
    if be%2: r+= 0 if ls(u%v,v)==1 else 1
    if al%2: r+= 0 if ls(w%v,v)==1 else 1
    return r%2
# ---------------- p-adic square root approximations ----------------
def padic_sqrt(c,v,N):
    """approx sqrt of c in Q_v (c Fraction, square in Q_v) as Fraction, precision ~ v^N relative"""
    k=vp(c.numerator,v)-vp(c.denominator,v); assert k%2==0
    u=c/Fraction(v)**k
    M=v**(N+3)
    un=(u.numerator*pow(u.denominator,-1,M))%M
    if v==2:
        assert un%8==1,un
        r=1
        for kk in range(3,N+3):
            if (r*r-un)%(2**(kk+1))!=0: r+=2**(kk-1)
        r%=M
    else:
        from sympy.ntheory import sqrt_mod
        r=sqrt_mod(un%v,v); assert r is not None
        r=int(r)
        mod=v
        while mod<M:       # Hensel/Newton
            mod=min(mod*mod,M); r=(r-(r*r-un)*pow(2*r,-1,mod))%mod
    return Fraction(r)*Fraction(v)**(k//2)
# ---------------- global conic points (brute force; used only for the generic validation) ----------------
def conic_point(A,B,C,bound=400):
    """primitive integer (X,Y,Z)!=0 with A X^2+B Y^2+C Z^2=0"""
    for Z in range(0,bound+1):
        for X in range(-bound,bound+1):
            if X==0 and Z==0: continue
            rhs=-(A*X*X+C*Z*Z)
            if rhs%B==0 and rhs//B>=0:
                Y2=rhs//B; Y=isqrt(Y2)
                if Y*Y==Y2:
                    g=gcd(gcd(X,Y),Z)
                    if g: return (X//g,Y//g,Z//g)
    return None
def global_points(e,beta):
    """q_i=(Gj*,Gk*,T*) with beta_j Gj^2 - beta_k Gk^2 + (e_j-e_k) T^2 = 0 ; (i,j,k) cyclic (0-based)"""
    qs={}
    for i in range(3):
        j=(i+1)%3; k=(i+2)%3
        pt=conic_point(beta[j],-beta[k],e[j]-e[k])
        if pt is None: return None
        qs[i]=(j,k,pt)
    return qs
# ---------------- local points on D_a ----------------
def local_point(e,beta,v,tries=200000):
    e1,e2,e3=e; cls=(lambda r:cls_odd(r,v)) if v>2 else cls_2
    cb=[cls(Fraction(b)) for b in beta]
    for t in range(tries):
        base=random.choice([e1,e2,e3,0,random.randint(-30,30)])
        k=random.choice([0,0,1,1,2,3]); u=rand_unit(v)+(v if t%7==0 else 0)
        if t%4==0: x=Fraction(u,v**(2*random.choice([1,2])))
        else: x=Fraction(base)+Fraction(v)**k*u
        if x in (e1,e2,e3): continue
        if cls(x-e1)==cb[0] and cls(x-e2)==cb[1] and cls(x-e3)==cb[2]: return x
    raise RuntimeError("no local point")

def coeffs(e,beta,qs,primitive=False):
    """tangent forms L_i = A_j G_j + A_k G_k + A_T T of H_i at q_i; primitive=True divides by the content"""
    out={}
    for i in range(3):
        j,k,(Gj,Gk,T)=qs[i]
        t=(Fraction(2*beta[j]*Gj,e[j]-e[k]),Fraction(-2*beta[k]*Gk,e[j]-e[k]),Fraction(2*T))
        if primitive:
            from math import lcm
            den=lcm(*[c.denominator for c in t]); ints=[int(c*den) for c in t]
            g=gcd(gcd(ints[0],ints[1]),ints[2])
            t=tuple(Fraction(z//g) for z in ints)     # rescaling by a positive rational: allowed by Hilbert reciprocity when all places are summed
        out[i]=t
    return out
def primes_of_fr(fr):
    ps=set()
    for z in (fr.numerator,fr.denominator):
        if abs(z)>1: ps|=set(factorint(abs(z)).keys())
    return ps
def place_value(e,beta,betap,qs,C,v,Nprec=16,reps=1):
    """sum_i (L_i(q_v),beta_i')_v for random non-degenerate local points q_v; returns the set of values seen (must be one value)."""
    vals=set()
    for r in range(reps):
        for attempt in range(200):
            x=local_point(e,beta,v)
            G=[padic_sqrt((x-e[i])/Fraction(beta[i]),v,Nprec)*random.choice([1,-1]) for i in range(3)]
            tot=0; good=True
            for i in range(3):
                j,k,_=qs[i]; Aj,Ak,AT=C[i]
                L=Aj*G[j]+Ak*G[k]+AT
                if L==0: good=False;break
                val=vp(L.numerator,v)-vp(L.denominator,v)
                if val>=Nprec-2: good=False;break
                tot+=hilb(L,betap[i],v)
            if good: vals.add(tot%2); break
        else: raise RuntimeError("no non-degenerate local point at %d"%v)
    return vals
def real_contribution(e,beta,betap,qs,C,xs=None):
    import mpmath
    mpmath.mp.dps=90
    es=sorted(e)
    cands=xs or [es[0]-10**6, es[0]-1, es[2]+1, es[2]+10**6, es[1]+(es[2]-es[1])/3, es[0]+(es[1]-es[0])/3, es[0]+(es[1]-es[0])*2/3]
    res=set()
    for x in cands:
        x=Fraction(x)
        if not all(((x-e[i])>0)==(beta[i]>0) for i in range(3)): continue
        G=[mpmath.sqrt(abs(mpmath.mpf((x-e[i]).numerator))/mpmath.mpf((x-e[i]).denominator)/abs(mpmath.mpf(beta[i]))) for i in range(3)]
        for sg in [(1,1,1),(1,-1,1),(-1,1,-1)]:
            tot=0
            for i in range(3):
                j,k,_=qs[i]; Aj,Ak,AT=C[i]
                L=mpmath.mpf(Aj.numerator)/Aj.denominator*sg[j]*G[j]+mpmath.mpf(Ak.numerator)/Ak.denominator*sg[k]*G[k]+mpmath.mpf(AT.numerator)/AT.denominator
                tot+= 1 if (L<0 and betap[i]<0) else 0
            res.add(tot%2)
    if len(res)!=1: raise RuntimeError("real place value depends on point/sign: %s"%res)
    return res.pop()
def pairing_bit(e,beta,betap,qs,places,Nprec=16,reps=1,primitive=False):
    places=sorted(set(places)-{0})+[0]     # each place exactly once (the real place v=0 last); duplicates would cancel in pairs
    C=coeffs(e,beta,qs,primitive); tot=0
    for v in places:
        if v==0:
            tot+=real_contribution(e,beta,betap,qs,C)
            continue
        vals=place_value(e,beta,betap,qs,C,v,Nprec,reps)
        if len(vals)>1: raise RuntimeError("place %d value depends on local point: %s"%(v,vals))
        tot+=vals.pop()
    return tot%2
def all_places(e,beta,betap,qs):
    D=abs((e[0]-e[1])*(e[0]-e[2])*(e[1]-e[2])); ps=set([2])|set(factorint(D).keys())
    for b in list(beta)+list(betap):
        if abs(b)>1: ps|=set(factorint(abs(b)).keys())
    C=coeffs(e,beta,qs)
    for i in C:
        for c in C[i]: ps|=primes_of_fr(c)
    for i in range(3):
        j,k,(Gj,Gk,T)=qs[i]
        for z in (Gj,Gk,T):
            if abs(z)>1: ps|=set(factorint(abs(z)).keys())
    return sorted(ps)+[0]
def places_S(e,beta,betap,factD=None):
    D=abs((e[0]-e[1])*(e[0]-e[2])*(e[1]-e[2])); ps=set([2])|set((factD or factorint(D)).keys())
    for b in list(beta)+list(betap):
        if abs(b)>1: ps|=set(factorint(abs(b)).keys())
    return sorted(ps)+[0]
def ct(e,a,ap,places=None,seed=0,qs_override=None,reps=1,primitive=False):
    """Cassels-Tate pairing bit <a,ap> on Sel^2 (a=(a1,a2)=([x-e1],[x-e2]) etc.)"""
    random.seed(seed)
    beta=(a[0],a[1],sqf(a[0]*a[1])); betap=(ap[0],ap[1],sqf(ap[0]*ap[1]))
    qs=qs_override or global_points(e,beta)
    if qs is None: return None
    if places is None: places=places_S(e,beta,betap) if primitive else all_places(e,beta,betap,qs)
    return pairing_bit(e,beta,betap,qs,places,reps=reps,primitive=primitive)

# ======================= validation on congruent number curves =======================
def congruent(ns):
    for n in ns:
        e=(-n,0,n); random.seed(n)
        els,gens,primes=sel2_general(e); d=len(els)
        print("n=%d dim Sel2=%d"%(n,d),flush=True)
        if d<4: continue
        M=[[ct(e,els[i],els[j],seed=1,reps=2,primitive=True) for j in range(d)] for i in range(d)]
        rows=[int(''.join(map(str,r)),2) for r in M]; b=[]; rk=0
        for r in rows:
            for x in b: r=min(r,r^x)
            if r: b.append(r); rk+=1
        print("  basis",els,"\n  pairing matrix",M,"rank",rk,flush=True)

# ======================= K=729 family: <(1,e), w2> on the B=+1 factor-shape curves =======================
K=729
def selmer_elements(P,Q):
    # Sel^2 of y^2=x(x-P^2)(x-Q^2) by the local images of 36-09EM/EN (as in code_sel2_symbolic_model / code_verify_09)
    D=abs(P*P-Q*Q)
    fP=[p for p in factorint(P) if p%2]; fQ=[p for p in factorint(Q) if p%2]
    fD=[p for p in factorint(D) if p%2 and p not in fP and p not in fQ]
    odd=sorted(fP+fQ+fD); gens=[-1,2]+odd; n=len(gens); rows=[]
    def addc(B,dim,cf):
        for h in annihilator(B,2*dim):
            row=[0]*(2*n)
            for gi,g in enumerate(gens):
                ca=cf(g)
                for t in range(dim):
                    if h[t] and ca[t]: row[gi]^=1
                    if h[dim+t] and ca[t]: row[n+gi]^=1
            rows.append(row)
    for v in odd:
        if v in fP: B=span_basis([[0,1,0,1],[0,0,0,1] if v%4==3 else [1,0,1,0]])
        elif v in fQ: B=span_basis([[0,1,0,0],[0,0,0,1] if v%4==3 else [1,0,0,0]])
        else: B=span_basis([[0,0,1,0],[0,0,0,1]])
        addc(B,2,lambda g,v=v:list(cls_odd(Fraction(g),v)))
    addc(local_image_2(P,Q),3,lambda g:list(cls_2(Fraction(g))))
    addc([[0,1]],1,lambda g:[1 if g<0 else 0])
    ker=annihilator(rows,2*n); els=[]
    for k in ker:
        a=1;b=1
        for gi,g in enumerate(gens):
            if k[gi]: a*=g
            if k[n+gi]: b*=g
        els.append((sqf(a),sqf(b)))
    return els
def target(j,seeds=(1,2)):
    u=17627+34440*j; P,Q=PQ_from_u(u); P=abs(P); Q=abs(Q)
    d,f,e=u,2*u+K,4*u+K
    els=selmer_elements(P,Q); G=elt_group(els)
    w1=(1,e); tors=[(1,-1),(1,sqf(-d*f*e))]
    assert w1 in G
    w2=[g for g in G if g not in elt_group([w1]+tors)][0]
    e3=(0,P*P,Q*Q); beta=(1,e,e); betap=(w2[0],w2[1],sqf(w2[0]*w2[1]))
    t=16*K*d*f      # t = (Q^2-P^2)/e
    qs={0:(1,2,(t+1,t-1,2)),1:(2,0,(0,Q,1)),2:(0,1,(P,0,1))}      # rational points on the three conics H_i
    for i in range(3):
        jj,kk,(X,Y,Z)=qs[i]; assert beta[jj]*X*X-beta[kk]*Y*Y+(e3[jj]-e3[kk])*Z*Z==0
    primes={2,3,d,e,f,7,41}|set(factorint(P))|set(factorint(Q))
    for b in list(beta)+list(betap):
        if abs(b)>1: primes|=set(factorint(abs(b)))
    from sympy import primerange
    places=sorted(primes|set(primerange(2,60)))+[0]
    out=[]
    for s in seeds:
        random.seed(s); out.append(pairing_bit(e3,beta,betap,qs,places,reps=2,primitive=True))
    chk=[]   # torsion classes must pair to 0
    for tt in tors:
        bt=(tt[0],tt[1],sqf(tt[0]*tt[1])); random.seed(5)
        pl=sorted((set(places)|{p for x in bt if abs(x)>1 for p in factorint(abs(x))})-{0})+[0]
        chk.append(pairing_bit(e3,beta,bt,qs,pl,reps=2,primitive=True))
    print({"j":j,"u":u,"dimSel2":len(els),"w2":w2,"pairing <(1,e),w2>":out,"torsion check":chk},flush=True)

if __name__=="__main__":
    if sys.argv[1]=="congruent": congruent([int(x) for x in sys.argv[2:]])
    else:
        for j in sys.argv[2:]: target(int(j))

# Log 0G: validation of the Cassels-Tate pairing implementation on congruent number curves y^2 = x^3 - n^2 x
# against Tunnell's theorem.  If the pairing on Sel^2/E[2] is nondegenerate then rank = 0, so n is not congruent,
# so Tunnell's counts are UNEQUAL (unconditional direction).  If L(E_n,1)=0 (counts equal; rank>=2 under BSD) the pairing must be trivial.
# Needs code_ct_cassels.py and code_sel2_rho.py in the same folder.
# Usage: python3 code_ct_validate_tunnell.py LO HI     (n in [LO,HI), n squarefree, n = 1,2,3 mod 8, dim Sel2 = 4)
import os, sys, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from math import isqrt
from sympy import factorint
from code_ct_cassels import sel2_general, ct, sqf

def sqfree(n): return all(k == 1 for k in factorint(n).values())
def rank2(M):
    rows = [int(''.join(map(str, r)), 2) for r in M]; b = []; rk = 0
    for r in rows:
        for x in b: r = min(r, r ^ x)
        if r: b.append(r); rk += 1
    return rk
def count(coef, m):
    a, b, c = coef; R = isqrt(m) + 2
    return sum(1 for x in range(-R, R+1) for y in range(-R, R+1) for z in range(-R, R+1) if a*x*x + b*y*y + c*z*z == m)
def tunnell_equal(n):
    if n % 2: return count((2, 1, 32), n) == count((2, 1, 8), n) / 2
    m = n // 2; return count((4, 1, 32), m) == count((4, 1, 8), m) / 2

if __name__ == "__main__":
    lo, hi = int(sys.argv[1]), int(sys.argv[2]); t0 = time.time()
    for n in range(lo, hi):
        if not sqfree(n) or n % 8 not in (1, 2, 3): continue
        e = (-n, 0, n)
        els, gens, primes = sel2_general(e); d = len(els)
        if d < 4: continue
        try:
            M = [[ct(e, els[i], els[j], seed=1, reps=2, primitive=True) for j in range(d)] for i in range(d)]
        except Exception as ex:
            print("n=%d skipped (%s)" % (n, repr(ex)[:60]), flush=True); continue
        if any(x is None for r in M for x in r):
            print("n=%d skipped (no conic point found by the brute-force search)" % n, flush=True); continue
        print("n=%d dimSel2=%d CTrank=%d Tunnell-counts-equal=%s" % (n, d, rank2(M), tunnell_equal(n)), flush=True)
